arguments.new_str:
var builder = WebApplication.CreateBuilder(args);

// Fix: Scoped IUserService was captured by singleton CacheService.
// .NET 9 enables ValidateOnBuild/ValidateScopes in development, which
// detects this and throws at startup. Register both as scoped.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });

// Fix: .NET 9 redacts all header values in Trace-level HttpClientFactory logs
// by default. Allowlist the non-sensitive headers you need to debug.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h => h != "X-Forwarded-For" && h != "X-Request-Id"));

builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});

